import json
from gbnf.rules_builder import RulesBuilder

cases = json.load(open('/tmp/cases.json'))
fails = 0
for key, grammar, exp in cases:
    b = RulesBuilder(grammar)
    got_rules = [
        [({'type': str(e.type), 'value': e.value} if e.value is not None else {'type': str(e.type)}) for e in rule]
        for rule in b.rules
    ]
    got_syms = [list(pair) for pair in b.symbol_ids]
    exp_syms = [list(p) for p in exp['symbolIds']]
    if got_rules != exp['rules']:
        fails += 1; print('RULES MISMATCH', key)
        for i,(g,e) in enumerate(zip(got_rules, exp['rules'])):
            if g != e: print(' rule', i, '\n  got', g, '\n  exp', e)
        if len(got_rules) != len(exp['rules']): print('  len', len(got_rules), len(exp['rules']))
    if got_syms != exp_syms:
        fails += 1; print('SYMBOLS MISMATCH', key, got_syms, exp_syms)
print(f'{len(cases)} reference RulesBuilder cases checked, {fails} mismatches')
"
